"""Two legal confirmed cancels; crossing uses an explicit teleport fixture."""
from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];h=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page();p.set_content(h.decode());p.wait_for_function('window.INKDuel?.ready');rows=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,V=INK.VisualFrame,rows=[],names=['frontArm','rearArm','frontLeg','rearLeg'],error=(a,b)=>Math.max(...names.flatMap(n=>a.joints3D[n].map((q,i)=>Math.hypot(...q.map((v,j)=>v-b.joints3D[n][i][j])))));
 for(const cross of [false,true]){A.start('ryu','ryu','training','classic',31);G.paused=false;document.getElementById('dummy').value='idle';document.getElementById('autohp').checked=false;A.teleport(0,600);A.teleport(1,735);A.step();const f=A.fighters[0];A.tryMove(0,'sMP');for(let i=0;i<40&&!f.attack?.hitConfirmed;i++)A.step();const confirmed=!!f.attack?.hitConfirmed,m=A.moves.ryu.find(m=>m.category==='special'&&!m.od&&A.canCancel(f,m));if(!m){rows.push({cross,confirmed,error:'no legal cancel',state:f.state,attack:f.attack?.m.id});continue;}for(let i=0;i<30&&!A.decide(0,m.id).ok;i++)A.step();if(cross)A.teleport(1,f.x-180);const before=V.get(A.visualPose(f)),dir=f.dir,accepted=A.tryMove(0,m.id),after=V.get(A.visualPose(f)),age0=error(before,after);let activeError=0,activeSamples=0;for(let i=0;i<80&&f.attack?.m.id===m.id;i++){A.step();if(f.attack&&f.attack.t>=m.startup&&f.attack.t<m.startup+m.active){const actual=V.get(A.visualPose(f)),view=Object.create(f);view._inkFrameTransition=null;const target=V.get(A.visualPose(view));for(const n of INK.FrameBridge.contactChains(f))for(let j=0;j<3;j++)activeError=Math.max(activeError,Math.hypot(...actual.joints3D[n][j].map((v,k)=>v-target.joints3D[n][j][k])));activeSamples++;}}rows.push({cross,fixture:cross?'opponent teleported across after real hit':'same side',confirmed,move:m.id,accepted,oldDir:dir,newDir:f.dir,age0Error:age0,activeError,activeSamples});}return rows;}''');b.close()
r={'htmlSha256':hashlib.sha256(h).hexdigest(),'cases':rows};(R/'qa/visual-frame/cancel.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r,indent=2));assert all(x.get('accepted') and x['confirmed'] and x['age0Error']<1e-6 and x['activeError']<1e-6 and x['activeSamples'] for x in rows)
